```python
import json
import re
from collections import Counter
# Constants
REPLACE_NONE = "None"
def task_func(json_str):
    data = json.loads(json_str)
    email_pattern = re.compile(r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b')
    def remove_none(obj):
        if isinstance(obj, dict):
            return {k: remove_none(v) for k, v in obj.items() if v is not None}
        elif isinstance(obj, list):
            return [remove_none(elem) for elem in obj if elem is not None]
        else:
            return obj
    def replace_emails(obj):
        if isinstance(obj, dict):
            return {k: replace_emails(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [replace_emails(elem) for elem in obj]
        elif isinstance(obj, str):
            return email_pattern.sub(REPLACE_NONE, obj)
        else:
            return obj
    data = remove_none(data)
    data = replace_emails(data)
    flat_data = []
    def flatten(obj):
        if isinstance(obj, dict):
            for v in obj.values():
                flatten(v)
        elif isinstance(obj, list):
            for elem in obj:
                flatten(elem)
        else:
            flat_data.append(obj)
    flatten(data)
    value_counts = Counter(flat_data)
    return {"data": data, "value_counts": value_counts}
